alsModule -->\n\nModuleMarvelRivalsRoutingModule->ModuleMarvelRivalsModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nModuleMarvelRivalsModule -->\n\nSharedModule->ModuleMarvelRivalsModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/modules/module-marvel-rivals/module-marvel-rivals.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            ListModuleMarvelRivalsComponent\n                        \n                        \n                            MarvelRivalsComponent\n                        \n                        \n                            TableModuleMarvelRivalsComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            ModuleMarvelRivalsRoutingModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { CommonModule } from '@angular/common';\n\nimport { ModuleMarvelRivalsRoutingModule } from './module-marvel-rivals-routing.module';\nimport { MarvelRivalsComponent } from './marvel-rivals.component';\nimport { ListModuleMarvelRivalsComponent } from './pages/list-module-marvel-rivals/list-module-marvel-rivals.component';\nimport { TableModuleMarvelRivalsComponent } from './components/table-module-marvel-rivals/table-module-marvel-rivals.component';\nimport { SharedModule } from '../shared/shared.module';\n\n\n@NgModule({\n  declarations: [\n    MarvelRivalsComponent,\n    ListModuleMarvelRivalsComponent,\n    TableModuleMarvelRivalsComponent\n  ],\n  imports: [\n    CommonModule,\n    SharedModule,\n    ModuleMarvelRivalsRoutingModule\n  ]\n})\nexport class ModuleMarvelRivalsModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"modules/ModuleMarvelRivalsRoutingModule.html":{"url":"modules/ModuleMarvelRivalsRoutingModule.html","title":"module - ModuleMarvelRivalsRoutingModule","body":"\n                   \n\n\n\n\n\n\n\n\n    Modules\n    ModuleMarvelRivalsRoutingModule\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/modules/module-marvel-rivals/module-marvel-rivals-routing.module.ts\n        \n\n\n\n\n\n        \n            \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { RouterModule, Routes } from '@angular/router';\nimport { ListModuleMarvelRivalsComponent } from './pages/list-module-marvel-rivals/list-module-marvel-rivals.component';\n\nconst routes: Routes = [\n  {\n    path: 'list-marvel-rivals',\n    component: ListModuleMarvelRivalsComponent\n  },\n  {\n    path: '**',\n    redirectTo: 'list-marvel-rivals'\n  }\n];\n\n@NgModule({\n  imports: [RouterModule.forChild(routes)],\n  exports: [RouterModule]\n})\nexport class ModuleMarvelRivalsRoutingModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"injectables/ModuleMarvelRivalsService.html":{"url":"injectables/ModuleMarvelRivalsService.html","title":"injectable - ModuleMarvelRivalsService","body":"\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n  Injectables\n  ModuleMarvelRivalsService\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            src/app/modules/module-marvel-rivals/services/module-marvel-rivals.service.ts\n        \n\n\n            \n                Description\n            \n            \n                Servicio para gestionar los personajes de Marvel Rivals.\nProporciona acceso al listado de héroes disponibles en la aplicación,\npermitiendo que los componentes de la vista consuman la información\ncentralizada en MARVEL_RIVALS_DATA.\nEste servicio está registrado a nivel raíz (providedIn: 'root') y puede\nser inyectado en cualquier componente del módulo que necesite consultar el\ncatálogo de personajes.\nExample :constructor(private marvelRivalsService: ModuleMarvelRivalsService) {}\n\n\nngOnInit() {\n  this.marvelRivalsService.getAllRivals().subscribe(characters => {\n    console.log(characters);\n  });\n}\n            \n\n\n\n            \n    Index\n    \n        \n\n                \n                    \n                        Methods\n                    \n                \n                \n                    \n                        \n                            \n                                getAllRivals\n                            \n                        \n                    \n                \n\n\n\n\n\n        \n    \n\n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                        getAllRivals\n                        \n                    \n                \n            \n            \n                \ngetAllRivals()\n                \n            \n\n\n                    \n                        \n                            Defined in src/app/modules/module-marvel-rivals/services/module-marvel-rivals.service.ts:38\n                        \n                    \n\n\n            \n                \n                        Obtiene todos los personajes disponibles del módulo Marvel Rivals.\n\n\n                        \n                            Returns :         Observable\n\n                        \n                            \n                                Observable con el listado de héroes (MarvelRivals[]).\n\n                            \n                \n            \n        \n    \n\n\n    \n\n\n    \n        import { Injectable } from '@angular/core';\nimport { MarvelRivals } from '../interfaces/module-marvel-rivals.interface';\nimport { Observable, of } from 'rxjs';\nimport { MARVEL_RIVALS_DATA } from '../../../core/config/marvel-rivals.config';\n\n/**\n * Servicio para gestionar los personajes de Marvel Rivals.\n *\n * Proporciona acceso al listado de héroes disponibles en la aplicación,\n * permitiendo que los componentes de la vista consuman la información\n * centralizada en `MARVEL_RIVALS_DATA`.\n *\n * @remarks\n * Este servicio está registrado a nivel raíz (`providedIn: 'root'`) y puede\n * ser inyectado en cualquier componente del módulo que necesite consultar el\n * catálogo de personajes.\n *\n * @example\n * ```ts\n * constructor(private marvelRivalsService: ModuleMarvelRivalsService) {}\n *\n * ngOnInit() {\n *   this.marvelRivalsService.getAllRivals().subscribe(characters => {\n *     console.log(characters);\n *   });\n * }\n * ```\n */\n@Injectable({\n  providedIn: 'root',\n})\nexport class ModuleMarvelRivalsService {\n  /**\n   * Obtiene todos los personajes disponibles del módulo Marvel Rivals.\n   *\n   * @returns Observable con el listado de héroes (`MarvelRivals[]`).\n   */\n  getAllRivals(): Observable {\n    return of(MARVEL_RIVALS_DATA);\n  }\n}\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"components/NavbarComponent.html":{"url":"components/NavbarComponent.html","title":"component - NavbarComponent","body":"\n                   \n\n\n\n\n\n\n\n\n\n  Components\n  \n  NavbarComponent\n\n\n\n        \n            Info\n      